import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`job-application-automation`,hasInputUrl:!1,heroTitle:`Automate your job applications in minutes`,heroSubtitle:`Perplexity Computer tailors your resume, writes cover letters in your voice, and surfaces matching roles automatically.`,heroOverlaySteps:[`Analyzing your resume, LinkedIn profile, and writing style`,`Building your personalized Job Application Hub`,`Configuring tailored resume and cover letter generation for each role`,`Application materials, pre-filled answers, and role matching ready to use`],generatingSteps:[`Mapping your resume, LinkedIn profile, and past cover letters into one reusable application system`,`Designing an agent to tailor resumes and cover letters for any role you paste in`,`Configuring application answer generation and role-matching logic`,`Setting up weekly job suggestions and interview-rate optimization`],featureSectionTitle:`From job listing to tailored application`,featureCardTitles:[`Connects to your career stack`,`Outputs you can submit`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Sheets, Notion, Gmail, and Google Drive plug into one workflow so tailored applications move straight from draft to submission.`,`Tailored resumes. Custom cover letters in your voice. Pre-filled application answers. Weekly role recommendations with match scores.`],capabilitySectionTitle:`Your career assistant, on autopilot`,capabilitySectionSubtitle:`Paste a job listing, step away, and come back to a ready-to-submit application.`,capabilityCards:[{title:`Resume Tailoring`,description:`Computer can rewrite your resume for each role by reordering experience, matching keywords, and highlighting the skills that matter most to that employer.`},{title:`Cover Letter Generation`,description:`Computer can draft cover letters in your voice by pulling from your past writing samples to match tone, structure, and storytelling style.`},{title:`Application Answers`,description:`Computer can pre-fill common application questions such as why this role, salary expectations, and availability using your profile and preferences.`},{title:`Connect Your Tools`,description:`Computer can export to Google Docs, Google Sheets, Notion, and Gmail so your entire job search stack stays connected.`},{title:`Learns Your Voice`,description:`Computer can remember your writing style, career goals, and past applications so every new cover letter and resume gets sharper over time.`},{title:`Weekly Job Alerts`,description:`Computer can scan new listings weekly, surface roles matching your profile, and flag ways to improve your interview rate based on application performance.`}]});export{t as default};
